const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el especialista en diagnóstico estructurado de RAX.\nTu función es procesar las declaraciones del emprendedor para extraer elementos de diagnóstico precisos.\nCATEGORÍAS PERMITIDAS DE RAX:\n- context, people_market, problem, solutions, financial, operational, commercial, legal, risk, open_question.\n\nREGLAS:\n1. Si la persona afirma algo sin datos verificables, clasifícalo como 'entrepreneur_statement'.\n2. Incluye siempre una cita textual (sourceQuote) del mensaje.\n3. Si detectas incertidumbre o contradicción con lo previo, márcalo explícitamente.\n4. Salida en formato JSON estricto con: extractedItems (array de objetos con category, title, content, infoType, uncertainty, sourceQuote), openQuestions (array de strings), uncertainties (array de strings).`;

const userPrompt = JSON.stringify({
  projectId: event.projectId,
  messageContent: payload.messageContent || payload.content || '',
  existingDiagnosisItems: payload.existingItems || []
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'https://rax-red.vercel.app') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

